                items: [{ key: 'pr-677', labels: [], issueNumber: null, prNumber: 677,
                          branch: 'ai/gh-676', author: 'ai-teammate', pr: { headSha: 'deadbeef77' } }],
                pr: { number: 677, body: 'Closes #676', head: { sha: 'deadbeef77' } },
