                pr: { number: 677, body: 'Closes #676', head: { sha: 'deadbeef77' } },
                prComments: [{ body: '⚠️ Merge conflict with main — cannot merge (head `deadbeef77`)' }],
                issue: { number: 676, state: 'open', labels: [{ name: 'agent:rework' }] }
            }
