            ]
        }
    }));
    sm2.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate', rules: [{
        source: 'github', query: { type: 'pr', mergeState: ['DIRTY'], draft: false },
        localAction: 'conflict_rework', limit: 1, id: 'conflict-rework' }] } });
