// gh-1027: per-tick scan budget for the conflict-rework rule. An
// already-reported DIRTY PR must not consume a rule-limit slot (gh-1025
// raised the limit 1 -> 5, which only pushed the starvation class out to
// 5+ parked markers): the engine loop scans candidates until `limit`
// ACTIONABLE ones were processed, and this module bounds the scan so a
// long parked queue cannot fan the per-tick github_get_pr_comments fetches
// without limit. Bounded, not eliminated (same tradeoff as gh-922's
// TRIGGER_FALLTHROUGH_RESERVE): 16+ parked markers ahead of the first
// unreported candidate re-starve one tick's slice.
//
// Shared by js/smAgent.js (the rule loop's break condition) and
// js/sm/sources/githubSource.js (queryPrs' candidate slice) — the two
// must agree, or the slice re-cuts the queue before the loop ever sees it.
'use strict';

var OVERSCAN = 15;

// Total candidates the conflict-rework rule may scan per tick for a given
// rule limit. limit null/invalid degrades to no over-scan (callers treat
// null limit as uncapped already).
function scanLimit(limit) {
   var l = (typeof limit === 'number' && isFinite(limit) && limit > 0)
       ? Math.floor(limit) : 0;
   return l + OVERSCAN;
}

if (typeof module !== 'undefined' && module.exports) {
   module.exports = { OVERSCAN: OVERSCAN, scanLimit: scanLimit };
}
