/**
 * Unit tests: the pack runtime LOAD self-test generator (gh-823).
 *
 * After every pack build the release extracts the zip, drops the generated
 * probe (renderProbeJs/renderProbeConfig) into it and runs `dmtools run` —
 * any module that fails to LOAD in the real runtime fails the release.
 * These tests pin the generated artifacts: the file selection, the probe's
 * failure reporting, and the config shape the runtime expects.
 *
 * Uses: loadModule(), suite(), test(), assert
 */

'use strict';

/* global loadModule, assert, test, suite */

function gen() {
    return loadModule('ci/pack_load_probe.cjs');
}

suite('pack load probe: file selection', function () {

    test('every packed js/ file is required, sorted, probe excluded', function () {
        var files = gen().probeFilesList([
            'js/smAgent.js',
            'js/common/smProvider.js',
            'manifest.json',
            'instructions/common/dmtools.md',
            '__pack_load_probe.js',
            'launch.json',
        ], '__pack_load_probe.js');
        assert.deepEqual(files, ['js/common/smProvider.js', 'js/smAgent.js']);
    });

    test('a Set-shaped walk works (the builder passes zip walks as Sets)', function () {
        var set = new Set();
        set.add('js/a.js');
        set.add('js/b/c.js');
        set.add('js/__pack_load_probe.js');
        assert.deepEqual(gen().probeFilesList(set, 'js/__pack_load_probe.js'),
            ['js/a.js', 'js/b/c.js']);
    });

    test('a non-js/ path is never required (the probe loads the payload only)', function () {
        var files = gen().probeFilesList(['root.js', 'docs/x.js', 'js/real.js'], 'p.js');
        assert.deepEqual(files, ['js/real.js']);
    });
});

suite('pack load probe: generated artifacts', function () {

    test('the probe requires every file and throws with the failing module named', function () {
        var src = gen().renderProbeJs(['js/a.js', 'js/b.js']);
        assert.contains(src, 'var FILES = ["js/a.js","js/b.js"];');
        assert.contains(src, 'function action() {');
        assert.contains(src, 'require(FILES[i])');
        assert.contains(src, 'pack runtime load self-test FAILED');
        // a missing module is captured per file and reported, never swallowed
        assert.contains(src, 'failed.push(FILES[i]');
    });

{"content":"// gh-1027: per-tick scan budget for the conflict-rework rule.
//
// An already-reported DIRTY PR must not consume a rule-limit slot: gh-1025
// raised the limit 1 -> 5, which only pushed the starvation class out to
// 5+ parked markers (live 2026-10-18: fa #983 parked every tick behind its
// own marker while unreported PRs were never evaluated, each still costing
// a github_get_pr_comments fetch). The engine loop now scans candidates
// until `limit` ACTIONABLE (unreported) ones were processed, and this
// module bounds that scan so a long parked queue cannot fan the per-tick
// comments fetches without limit.
//
// Bounded, not eliminated (the same tradeoff gh-922's
// TRIGGER_FALLTHROUGH_RESERVE documents): parked markers beyond the budget
// ahead of the first unreported candidate re-starve one tick's slice —
// they drain as their rework legs land, so the bound only ever costs a
// tick of delay, never a deadlock.
//
// Shared by js/smAgent.js (the rule loop's break condition) and
// js/sm/sources/githubSource.js (queryPrs' candidate slice) — the two must
// agree, or the query slice re-cuts the queue before the loop ever sees
// the candidates behind the parked markers.
'use strict';

// Extra already-reported candidates a tick may scan past the rule limit.
var OVERSCAN = 15;

// Total candidates the conflict-rework rule may scan per tick for a given
// rule limit. A non-positive/invalid limit degrades to the overscan alone
// (callers with no rule limit are uncapped anyway and never consult this).
function scanLimit(limit) {
    var l = (typeof limit === 'number' && isFinite(limit) && limit > 0)
        ? Math.floor(limit) : 0;
    return l + OVERSCAN;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { OVERSCAN: OVERSCAN, scanLimit: scanLimit };
}
